# Manifests that must not build: app | text the build error must contain.
BUILD_FAILS=(
  "http-port-clash | port 80 is declared by web (service web) and other (service other)"
)

# Checks that run on the host alone: name | command that must succeed.
HOST_CHECKS=(
  "noise-vectors | cargo test -q -p noise --target x86_64-unknown-linux-gnu && python3 -c 'import json, sys; sys.path.insert(0, \"tools\"); import vanir_noise; p = vanir_noise.check_vector(json.load(open(\"tests/vectors/noise-ik.json\"))); print(p or \"python: all match\"); sys.exit(bool(p))'"
)

trim() { local s="$1"; s="${s#"${s%%[![:space:]]*}"}"; echo "${s%"${s##*[![:space:]]}"}"; }

failed=0
for check in "${HOST_CHECKS[@]}"; do
  IFS='|' read -r name command <<<"$check"
  name=$(trim "$name"); command=$(trim "$command")
  [[ "$name" =~ ${ONLY:-.} ]] || continue
  if check_log=$(bash -c "$command" 2>&1); then
    echo "PASS $name"
  else
    echo "FAIL $name"; tail -10 <<<"$check_log" | sed 's/^/    /'; failed=1
  fi
done
for case in "${BUILD_FAILS[@]}"; do
  IFS='|' read -r app want <<<"$case"
  app=$(trim "$app"); want=$(trim "$want")
  [[ "build-$app" =~ ${ONLY:-.} ]] || continue
  if build_log=$(make -s kernel APP="tests/apps/$app.toml" 2>&1); then
    echo "FAIL build-$app: the manifest built"; failed=1
  elif grep -qF -- "$want" <<<"$build_log"; then
    echo "PASS build-$app (refused)"
  else
    echo "FAIL build-$app: refused, but without: $want"; tail -5 <<<"$build_log" | sed 's/^/    /'; failed=1
  fi
done
for case in "${CASES[@]}"; do
  IFS='|' read -r name app user kernel env want_status want_text <<<"$case"
  name=$(trim "$name"); app=$(trim "$app"); env=$(trim "$env"); user=$(trim "$user"); kernel=$(trim "$kernel")
  [[ "$name" =~ ${ONLY:-.} ]] || continue
  want_status=$(trim "$want_status"); want_text=$(trim "$want_text")

  [[ "${SLOW:-1}" == 0 && " $env " == *" SLOW=1 "* ]] && { echo "SKIP $name: slow"; continue; }
  vars=(ACCEL="${ACCEL:-tcg}" $env)
  limit=60
  for v in $env; do [[ "$v" == TIMEOUT=* ]] && limit=${v#TIMEOUT=}; done
  wrap=()
  if [[ " $env " == *" TRANSPORT=vsock "* ]]; then
    # vhost-vsock needs /dev/vhost-vsock (the kvm group): use `sg kvm` if this login predates it.
    if [ -w /dev/vhost-vsock ]; then wrap=(bash -c)
    elif sg kvm -c 'test -w /dev/vhost-vsock' 2>/dev/null; then wrap=(sg kvm -c)
    else echo "SKIP $name: no access to /dev/vhost-vsock (join the kvm group)"; continue
    fi
  fi
  if [[ " $env " == *" NODES=2 "* ]]; then
    # Two nodes, the control plane and the peer: tests/two-nodes.sh does it all.
    out=$(tests/two-nodes.sh "$app" "$user" "$kernel" "$limit" "${vars[@]}" 2>&1)
    status=$?
    out=$(sed 's/\x1b\[[0-9;:?=]*[A-Za-z]//g; s/\x1b[()][0-9A-Za-z]//g; s/\r//g' <<<"$out")
  else
    if ! build_log=$(make -s image APP="tests/apps/$app.toml" USER_FEATURES="$user" KERNEL_FEATURES="$kernel" "${vars[@]}" 2>&1); then
      echo "FAIL $name: build failed"; echo "$build_log"; failed=1; continue
    fi
    qemu=$(make -s qemu-cmd "${vars[@]}")
    peer=""
    for v in $env; do [[ "$v" == PEER=* ]] && peer=${v#PEER=}; done
    # CP=<scenario> runs the mock control plane next to QEMU (CP_ARGS=a,b,c adds options); its
    # output is checked with the serial log, after a "--- control plane ---" line.
    cp=""
    cp_args=()
    for v in $env; do
      [[ "$v" == CP=* ]] && cp=${v#CP=}
      [[ "$v" == CP_ARGS=* ]] && IFS=, read -r -a cp_args <<<"${v#CP_ARGS=}"
    done
    if [ -n "$cp" ]; then
      rm -f build/cp.log build/cp-telemetry.log
      tools/control-plane.py "$cp" --timeout "$limit" "${cp_args[@]}" >build/cp.log 2>&1 &
      cp_pid=$!
      sleep 0.5
    fi
    if [ -n "$peer" ]; then
      rm -f build/peer.log
      tools/net-peer.py "$peer" --timeout "$limit" >build/peer.log 2>&1 &
      peer_pid=$!
    fi
    if [ ${#wrap[@]} -ne 0 ]; then
      rm -f build/telemetry.log
      agent_args=()
      [[ " $env " == *" ATTEST=1 "* ]] && agent_args+=(--attest)
      for v in $env; do
        [[ "$v" == RELEASE=* ]] && agent_args+=(--release-key keys/master.key --reference "${v#RELEASE=}")
        [[ "$v" == INTERVAL=* ]] && agent_args+=(--set-interval "${v#INTERVAL=}")
        [[ "$v" == ATTEST_DELAY=* ]] && agent_args+=(--attest-delay "${v#ATTEST_DELAY=}")
        [[ "$v" == ATTEST_DELAY=* ]] && agent_args+=(--attest-delay "${v#ATTEST_DELAY=}")
      done
      tools/host-agent.py --listen-vsock 5000 --save build/telemetry.log --quiet "${agent_args[@]}" >/dev/null 2>&1 &
      agent=$!
      for _ in $(seq 50); do [ -e build/telemetry.log ] && break; sleep 0.1; done
      out=$(timeout "$limit" "${wrap[@]}" "$qemu" 2>&1)
      status=$?
      sleep 0.5; kill $agent 2>/dev/null; wait $agent 2>/dev/null
    else
      out=$(timeout "$limit" $qemu 2>&1)
      status=$?
    fi
    # Firmware consoles (OVMF under BOOT=uefi-secure) position every character with escape codes;
    # match against plain text.
    out=$(sed 's/\x1b\[[0-9;:?=]*[A-Za-z]//g; s/\x1b[()][0-9A-Za-z]//g; s/\r//g' <<<"$out")
    if [ -n "$peer" ]; then
      # The peer finishes on its own once the guest is done; give it a moment, then stop it.
      for _ in $(seq 50); do kill -0 $peer_pid 2>/dev/null || break; sleep 0.1; done
      kill $peer_pid 2>/dev/null; wait $peer_pid 2>/dev/null
      out+=$'\n--- peer ---\n'"$(cat build/peer.log)"
    fi
    if [ -n "$cp" ]; then
      for _ in $(seq 30); do kill -0 $cp_pid 2>/dev/null || break; sleep 0.1; done
      kill $cp_pid 2>/dev/null; wait $cp_pid 2>/dev/null
      out+=$'\n--- control plane ---\n'"$(cat build/cp.log)"
    fi
  fi
  # What reached the host over the virtio console, for the checks below.
  out+=$'\n--- build/telemetry.log ---\n'"$(cat build/telemetry.log 2>/dev/null)"

  if [[ "$want_text" == re:* ]]; then
    grep -Pzq -- "${want_text#re:}" <<<"$out"; text_ok=$?
  elif [[ "$want_text" == cmd:* ]]; then
    check_out=$(bash -c "${want_text#cmd:}" <<<"$out" 2>&1); text_ok=$?
    [ "$text_ok" -eq 0 ] || echo "    check: $check_out"
  else
    grep -qF -- "$want_text" <<<"$out"; text_ok=$?
  fi

  if [ "$status" -eq "$want_status" ] && [ "$text_ok" -eq 0 ]; then
    echo "PASS $name (status $status)"
  else
    echo "FAIL $name: status $status (want $want_status), want text: $want_text"
    sed 's/^/    /' <<<"$out"
    failed=1
  fi
done
exit $failed